function getQliksenseaiTranslation(key, lang) {
    if (qliksenseaiTranslations[lang] && qliksenseaiTranslations[lang][key]) {
        return qliksenseaiTranslations[lang][key];
    }
    if (qliksenseaiTranslations.en && qliksenseaiTranslations.en[key]) {
        return qliksenseaiTranslations.en[key];
    }
    return null;
}

function applyQliksenseaiTranslations(lang) {
    console.log('Applying qlik-sense-ai translations for:', lang);
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && key.startsWith('review.qlik-sense-ai.')) {
            const translation = getQliksenseaiTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    console.log(`Applied ${count} qlik-sense-ai translations`);
}

document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyQliksenseaiTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyQliksenseaiTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyQliksenseaiTranslations(currentLang);
}

console.log('qlik-sense-ai i18n loaded');
